import pandas as pd

def clean(df):
    d = df.copy()
    d['Category'] = d['Category'].str.strip().replace({
        'Furnture': 'Furniture',
        'Accesories': 'Accessories'
    })
    d = d.drop_duplicates()
    return d

def answer(df):
    d = clean(df)
    counts = d.groupby('Category', dropna=True).size()
    return {str(k): int(v) for k, v in counts.items()}
